//! Code generated by `TrivialType` derive must not depend on the prelude, which is not available
//! in modules with `#[no_implicit_prelude]`

#[no_implicit_prelude]
mod no_implicit_prelude {
    use ::ab_io_type::trivial_type::TrivialType;
    use ::ab_io_type::unaligned::Unaligned;
    use ::core::clone::Clone;
    use ::core::marker::Copy;

    #[derive(Copy, Clone, TrivialType)]
    #[repr(C)]
    struct Struct {
        a: u8,
        b: [u8; 3],
    }

    #[derive(Copy, Clone, TrivialType)]
    #[repr(transparent)]
    struct TupleStruct(u32);

    #[derive(Copy, Clone, TrivialType)]
    #[repr(u8)]
    enum Enum {
        A { a: u8 },
        B { b: u8 },
    }

    #[derive(Copy, Clone, TrivialType)]
    #[repr(u8)]
    enum TupleVariants {
        A(u8, Unaligned<u16>),
        B([u8; 3]),
    }

    #[derive(Copy, Clone, TrivialType)]
    #[repr(u8)]
    enum ExplicitDiscriminants {
        A = 0,
        B = 1,
    }

    #[derive(Copy, Clone, TrivialType)]
    #[repr(C)]
    #[trivial_type(validate = Self::is_valid)]
    struct Validated {
        value: u32,
    }

    impl Validated {
        const fn is_valid(value: Self) -> bool {
            value.value != u32::MAX
        }
    }

    trait Check {
        fn check(value: Self) -> bool;
    }

    #[derive(Copy, Clone, TrivialType)]
    #[repr(C)]
    #[trivial_type(validate = <Self as Check>::check)]
    struct QualifiedValidated {
        value: u32,
    }

    impl Check for QualifiedValidated {
        fn check(value: Self) -> bool {
            value.value != u32::MAX
        }
    }
}

fn main() {}
